-- Under PostgreSQL SERIALIZABLE, SSI tracks predicate reads:
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT COALESCE(SUM(gpus), 0) FROM allocations WHERE project_id = 42;
-- If concurrent tx also read and inserted for project_id = 42, COMMIT raises SQLSTATE 40001
INSERT INTO allocations (project_id, gpus) VALUES (42, 4);
COMMIT;

-- MySQL 8.0 InnoDB: Next-Key Lock blocks phantom INSERTs into project_id = 42
START TRANSACTION;
SELECT SUM(gpus) FROM allocations WHERE project_id = 42 FOR UPDATE;
INSERT INTO allocations (project_id, gpus) VALUES (42, 4);
COMMIT;

CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE oncall_shifts
ADD CONSTRAINT no_overlapping_shifts
EXCLUDE USING gist (team_id WITH =, tstzrange(start_ts, end_ts) WITH &&);
